<div class="chat-widget"><button class="floating-button chat-color" data-bs-toggle="offcanvas" data-bs-target="#chatPanel" aria-label="Chat assistant">💬</button></div><div class="offcanvas offcanvas-end" id="chatPanel"><div class="offcanvas-header"><h5>Restaurant Assistant</h5><button class="btn-close" data-bs-dismiss="offcanvas"></button></div><div class="offcanvas-body d-flex flex-column"><div id="chatMessages" class="chat-messages flex-grow-1"><div class="chat-bubble bot">Hello. Ask me about the menu, prices, orders or reservations.</div></div><form id="chatForm" class="d-flex gap-2 mt-3"><input id="chatInput" class="form-control" maxlength="1000" placeholder="Type your message"><button class="btn btn-primary">Send</button></form></div></div>
